  "hoja.anadir": "How would you like to add your medication?", "via.buscar": "Search by name", "via.buscar.x": "Type the brand or active ingredient and the dose", "via.foto.x": "The app reads names and doses from the sheet", "via.caja.x": "One medicine at a time", "via.pdf.x": "Discharge report or e-prescription", "via.pegar.x": "One medicine per line", "via.dictar.x": "Say the name and the dose", "via.barras.x": "With the camera, on the box",
